  background: #49b1f5;
  box-shadow: 0 0 0 4px rgba(73, 177, 245, 0.2);
}

#archive .article-sort-item.no-article-cover {
  height: auto;
}

#archive .article-sort-item.year {
  font-size: 1.25em;
  font-weight: 700;
  color: #ffffff;
  background: linear-gradient(135deg, #49b1f5 0%, #2c8fd4 100%);
  transform: none !important;
  box-shadow: 0 4px 16px rgba(73, 177, 245, 0.3);
  padding: 10px 20px;
  border-left: none;
}

#archive .article-sort-item.year:before {
  left: -36px;
  background: #ffffff;
  border: 2px solid #49b1f5;
  width: 14px;
  height: 14px;
  box-shadow: 0 0 0 3px rgba(73, 177, 245, 0.3);
}

