  color: #ffffff;
  box-shadow: 0 4px 16px rgba(73, 177, 245, 0.25);
}

[data-theme="dark"] #archive .article-sort-item-year:before {
  background: #1e1e1e;
  border-color: #49b1f5;
  box-shadow: 0 0 0 3px rgba(73, 177, 245, 0.3);
}

[data-theme="dark"] #archive .article-sort-item-year:hover {
