  justify-content: space-between;
}

#nav #blog-info {
  flex: none;
  flex-shrink: 0;
}

#nav #menus {
  flex: 1;
  display: flex;
  justify-content: center;
  align-items: center;
}

#nav #menus .menus_items {
  display: flex;
  align-items: center;
  justify-content: center;
}

#nav #menus .menus_items .menus_item {
  padding: 0 0 0 14px;
}

#nav #nav-right {
  display: flex;
  align-items: center;
  flex-shrink: 0;
  gap: 20px;
}

