#nav #nav-right .nav-right-item .menus_item_child li:first-child a {
  border-top-left-radius: 8px;
  border-top-right-radius: 8px;
}

#nav #nav-right .nav-right-item .menus_item_child li:last-child a {
  border-bottom-right-radius: 8px;
  border-bottom-left-radius: 8px;
}

[data-theme="dark"] #nav #nav-right .nav-right-item .menus_item_child {
  background: rgba(30, 30, 30, 0.96) !important;
}

[data-theme="dark"] #nav #nav-right .nav-right-item .menus_item_child li a {
  color: #e0e0e0 !important;
}

#nav.hide-menu #menus {
  display: none;
}

#nav.hide-menu #nav-right #toggle-menu {
  display: inline-block;
}

@media screen and (max-width: 768px) {
  #nav #menus {
    display: none;
  }
  #nav #nav-right #toggle-menu {
    display: inline-block;
  }
}

#nav .site-name {
  font-size: 22px;    /* 站点名称 */
}

#nav .menus_item .menus_item_child {
  background: rgba(255, 255, 255, 0.96) !important;
  backdrop-filter: blur(16px) !important;
  -webkit-backdrop-filter: blur(16px) !important;
  border-radius: 8px !important;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.25) !important;
